SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0670000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 67, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "67", "printedPageNumber": 67, "pdfPageNumber": 450, "sequenceIndex": 57, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0670100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0670200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER I", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0670300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "QUOTATIONS FROM THE QUR''AN", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0670400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—I", "sourceIdentifier": null, "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0670000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "PART III", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670100-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "IMPORTANCE OF SINCERITY AND DEVOTION IN SALAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670200-0000-4000-8000-000000000001", "structuralNodeId": "b0670100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There are many persons who offer their salaat and quite a lot of them are particular about jamaat as well, but they say it so imperfectly that, instead of earning blessings and reward for them, it is rejected forthwith. This, however, is not so bad as to discard salaat altogether, which as we have already learnt, is very serious. Although we are deprived of the rewards by saying a defective salaat, which is not accepted, yet we are saved from the insolence of neglecting and disobeying Allah''s commandments. However, when we spend our time, leave our work and undergo inconvenience, then why should we not see that we get the best return for our time and labour by saying our salaat as best as we can?\n\nThis third part is divided into three chapters. In the first chapter, a few quotations from the Holy Qur''an about the people who are condemned for their bad salaat and those who are praised for their good salaat, are given. In the second Chapter, stories about the salaat of a few lovers of Allah are collected. The third chapter consists of the sayings of the Prophet (Sallallaho alaihe wasallam) on this subject.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670300-0000-4000-8000-000000000001", "structuralNodeId": "b0670200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670400-0000-4000-8000-000000000001", "structuralNodeId": "b0670300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "QUOTATIONS FROM THE QUR''AN", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670500-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670600-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670700-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Their flesh and their blood reach not Allah, but devotion from you reacheth to Him.\" (XXII: 37)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}, {"id": "f0670800-0000-4000-8000-000000000001", "structuralNodeId": "b0670400-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Although this particular verse refers to the animal sacrifice, yet in principle it equally applies to all other rituals. It is sincerity and devotion in a service by which its acceptance would be judged by Allah. Hadhrat Mu''aaz (Radhiyallaho", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 67"}]}'::jsonb);